import { createRequire } from 'module';
const require = createRequire(import.meta.url);
const PDFDocument = require('pdfkit');

/**
 * Generates a clean, structured PDF Buffer from an OmniStudy AI note object.
 * @param {Object} note - The comprehensive note object generated by geminiService.
 * @returns {Promise<Buffer>} - Resolves with the PDF buffer.
 */
export async function generateNotePdfBuffer(note) {
  return new Promise((resolve, reject) => {
    try {
      const doc = new PDFDocument({
        bufferPages: true,
        margin: 40,
        size: 'A4',
        info: {
          Title: note.title || 'OmniStudy AI Lecture Notes',
          Author: 'OmniStudy AI',
          Subject: note.subject || 'Academic Notes'
        }
      });

      const buffers = [];
      doc.on('data', chunk => buffers.push(chunk));
      doc.on('end', () => resolve(Buffer.concat(buffers)));
      doc.on('error', err => reject(err));

      const primaryColor = '#1E3A8A'; // Deep Navy
      const accentColor = '#D97706';  // Warm Amber
      const textColor = '#1F2937';    // Dark Slate
      const mutedColor = '#6B7280';   // Gray
      const stickyBg = '#FEF3C7';     // Light Amber for sticky notes

      // Header Banner
      doc.rect(40, 40, 515, 60).fill('#EEF2FF');
      doc.fillColor(primaryColor).fontSize(18).text(note.title || 'OmniStudy AI - Lecture Master Notes', 55, 52, { width: 485, ellipsis: true });
      doc.fillColor(mutedColor).fontSize(10).text(`Subject: ${note.subject || 'General'} | Exam: ${note.targetExam || 'All University / Board Exams'} | OmniStudy AI`, 55, 76);

      doc.moveDown(3);

      // Section: Summary / Overview
      if (note.summary) {
        doc.fillColor(primaryColor).fontSize(14).text('📌 Core Chapter Summary', { underline: true });
        doc.moveDown(0.5);
        doc.fillColor(textColor).fontSize(10.5).lineGap(2).text(note.summary);
        doc.moveDown(1.5);
      }

      // Section: Key Concepts
      if (Array.isArray(note.keyConcepts) && note.keyConcepts.length > 0) {
        doc.fillColor(primaryColor).fontSize(14).text('✍️ Key Concepts & Deep Breakdown', { underline: true });
        doc.moveDown(0.8);

        note.keyConcepts.forEach((concept, idx) => {
          // Check page break
          if (doc.y > 680) {
            doc.addPage();
          }

          const heading = concept.heading || `Concept #${idx + 1}`;
          doc.fillColor(accentColor).fontSize(12).text(`${idx + 1}. ${heading}`);
          doc.moveDown(0.3);

          if (concept.explanation || concept.content) {
            doc.fillColor(textColor).fontSize(10).lineGap(1.5).text(concept.explanation || concept.content);
            doc.moveDown(0.4);
          }

          // Bullet points
          if (Array.isArray(concept.points) && concept.points.length > 0) {
            concept.points.forEach(pt => {
              doc.fillColor(textColor).fontSize(9.5).text(`  • ${pt}`);
            });
            doc.moveDown(0.4);
          }

          // Formulas if present
          if (Array.isArray(concept.formulas) && concept.formulas.length > 0) {
            doc.fillColor('#991B1B').fontSize(9.5).text(`  ⚡ Formulas: ${concept.formulas.join(', ')}`);
            doc.moveDown(0.3);
          }

          // Memory Tip if present
          if (concept.memoryTip) {
            doc.fillColor('#065F46').fontSize(9.5).text(`  💡 Memory Tip: ${concept.memoryTip}`);
            doc.moveDown(0.3);
          }

          doc.moveDown(0.8);
        });
      }

      // Section: Important Formulas & Cheat Sheet
      if (Array.isArray(note.formulas) && note.formulas.length > 0) {
        if (doc.y > 650) doc.addPage();
        doc.fillColor(primaryColor).fontSize(14).text('⚡ Formula Sheet & Cheat Sheet', { underline: true });
        doc.moveDown(0.5);

        note.formulas.forEach((item, fIdx) => {
          const formulaStr = typeof item === 'string' ? item : `${item.name || item.title || 'Formula'}: ${item.formula || item.content || ''}`;
          doc.fillColor('#B45309').fontSize(10).text(`  [${fIdx + 1}] ${formulaStr}`);
        });
        doc.moveDown(1.5);
      }

      // Section: Previous Year Questions (PYQs)
      const questions = note.pyqs || note.practiceQuestions || note.mcqs || [];
      if (Array.isArray(questions) && questions.length > 0) {
        if (doc.y > 620) doc.addPage();
        doc.fillColor(primaryColor).fontSize(14).text('🎯 Exam PYQs & Important Practice Questions', { underline: true });
        doc.moveDown(0.6);

        questions.slice(0, 10).forEach((q, qIdx) => {
          if (doc.y > 700) doc.addPage();
          const qText = typeof q === 'string' ? q : (q.question || q.q || JSON.stringify(q));
          doc.fillColor(textColor).fontSize(10).text(`Q${qIdx + 1}: ${qText}`);

          if (q.answer || q.solution) {
            doc.fillColor('#047857').fontSize(9).text(`Ans: ${q.answer || q.solution}`);
          }
          doc.moveDown(0.5);
        });
      }

      // Footer on all pages
      try {
        const pages = doc.bufferedPageRange();
        for (let i = 0; i < pages.count; i++) {
          doc.switchToPage(i);
          doc.fillColor(mutedColor).fontSize(8).text(
            `OmniStudy AI - Generated with Gemini AI & MERN Stack | Page ${i + 1} of ${pages.count}`,
            40,
            780,
            { align: 'center', width: 515 }
          );
        }
      } catch (footerErr) {
        console.warn('[pdfService] Footer pagination warning:', footerErr.message);
      }

      doc.end();
    } catch (err) {
      reject(err);
    }
  });
}
